package com.gameaggregator.studioservice.api;
import com.gameaggregator.platform.core.common.web.ApiResponse; import com.gameaggregator.studioservice.application.StudioService; import com.gameaggregator.studioservice.domain.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/studios") public class StudioController {final StudioService s; public StudioController(StudioService s){this.s=s;} @PostMapping @ResponseStatus(HttpStatus.CREATED) ApiResponse<Studio> create(@Valid @RequestBody StudioDtos.Create r){return ApiResponse.success(s.create(r));} @GetMapping ApiResponse<List<Studio>> list(){return ApiResponse.success(s.list());} @GetMapping("/{id}") ApiResponse<Studio> get(@PathVariable UUID id){return ApiResponse.success(s.get(id));} @PutMapping("/{id}") ApiResponse<Studio> update(@PathVariable UUID id,@Valid @RequestBody StudioDtos.Update r){return ApiResponse.success(s.update(id,r));} @PatchMapping("/{id}/status") ApiResponse<Studio> status(@PathVariable UUID id,@Valid @RequestBody StudioDtos.Status r){return ApiResponse.success(s.status(id,r));} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable UUID id){s.delete(id);} @GetMapping("/{id}/members") ApiResponse<List<StudioMember>> members(@PathVariable UUID id){return ApiResponse.success(s.members(id));} @PostMapping("/{id}/invites") ApiResponse<StudioMember> invite(@PathVariable UUID id,@Valid @RequestBody StudioDtos.Invite r){return ApiResponse.success(s.invite(id,r));} @PostMapping("/{id}/contacts") ApiResponse<StudioContact> contact(@PathVariable UUID id,@Valid @RequestBody StudioDtos.Contact r){return ApiResponse.success(s.contact(id,r));}}
